        "This mini game will only be required when you are opening the back of a bank truck.": "Ce mini-jeu est uniquement requis pour ouvrir l'arrière d'un fourgon blindé.",
        "This feature locks any bank truck that players attempt to enter, ensuring that they must rob the truck at its current location. It prevents players from driving the truck elsewhere to rob it, adding a layer of challenge and realism to the robbery process.": "Cette option verrouille les fourgons blindés dans lesquels les joueurs essaient de monter. Ils doivent ainsi les braquer sur place et ne peuvent pas les déplacer ailleurs, ce qui rend le braquage plus difficile et réaliste.",
        "Enable two guards to exit the truck and engage in combat after players how blown open the back of the bank truck": "Permet à deux gardes de sortir du fourgon et d'engager le combat après l'explosion des portes arrière.",
        "By default, GTA 5 spawns bank trucks at three different locations at random times of the day. Adding new spawn locations will not remove the built-in locations. Instead, it will allow a bank truck to randomly spawn at one of your set locations every hour, unless the \"Initiating Starting Point\" option is checked, in which case a random spawn location will be selected for that setting.": "Par défaut, GTA 5 fait apparaître des fourgons blindés à trois endroits à des heures aléatoires. Ajouter des points d'apparition ne supprime pas ceux du jeu. Un fourgon pourra apparaître à l'un de vos points chaque heure. Si l'option « Point de départ » est activée, un point sera choisi aléatoirement pour ce départ.",
        "Add Truck Spawn": "Ajouter un point d'apparition du fourgon",
        "Set an item required to initiate the bank truck robbery": "Définissez un objet requis pour commencer le braquage du fourgon blindé.",
        "Add Item": "Ajouter un objet",
        "Reward Item": "Objet de récompense",
        "Set an item as a reward": "Définissez un objet à donner en récompense.",
        "This option allows you to make the bank truck robbery like a traditional staged robbery where as without this, players will have to find spawned bank trucks. (You need to place Dynamic Spawn Locations for this to work | Bank trucks randomly found out in the world will not be robbable if this is checked)": "Cette option transforme le braquage du fourgon en braquage à étapes. Sans elle, les joueurs doivent trouver un fourgon déjà apparu. Vous devez définir des points d'apparition dynamiques. Les fourgons trouvés aléatoirement dans le monde ne seront pas braquables si cette option est activée.",
        "Set Starting Point Position": "Définir la position du point de départ",
        "Lockpick": "Crochetage",
        "Hacking": "Piratage",
        "If checked, a blip of the bank truck will be visible on the map for all players. This will create a dynamic of other members in the server possibly fighting for the bank truck.": "Affiche le fourgon blindé sur la carte de tous les joueurs. D'autres joueurs pourront ainsi le repérer et se disputer son butin.",
        "When checked, sets all other robberies on cooldown when the bank truck is hit": "Met tous les autres braquages en temps de recharge lorsque le fourgon est attaqué.",
        "Reward Money": "Récompense en argent",
        "Set a reward amount in cash or bank": "Définissez une récompense en espèces ou sur le compte bancaire.",
        "Set cooldown time before bank truck can be hit again": "Définissez le délai avant de pouvoir attaquer à nouveau le fourgon.",
