        "Set the number of police required to trigger the bank truck robbery (this checks for anyone with the job police, bcso, leo, ranger, trooper, or sasp)": "Définissez le nombre de policiers requis pour le braquage du fourgon. Les métiers vérifiés sont police, bcso, leo, ranger, trooper et sasp.",
