        "This stage does not have a valid Target Vector yet.": "Cette étape ne possède pas encore de coordonnées de cible valides.",
        "Door changed. Re-place this keypad target before saving so it does not keep the old robbery position.": "Porte modifiée. Replacez la cible de ce clavier avant d'enregistrer pour éviter de conserver l'ancienne position du braquage.",
        "You cannot duplicate a CUSTOM DOOR step.": "Vous ne pouvez pas dupliquer une étape de PORTE PERSONNALISÉE.",
